input pixel image img;
param float inBlack = 0.0 [0.0, 1.0];
param float inWhite = 1.0 [0.0, 1.0];
param float gamma = 1.0 [0.1, 4.0];
param float outBlack = 0.0 [0.0, 1.0];
param float outWhite = 1.0 [0.0, 1.0];
c = clamp((img.rgb - inBlack) / max(inWhite - inBlack, 0.0001), 0.0, 1.0);
col = outBlack + pow(c, 1.0 / max(gamma, 0.0001)) * (outWhite - outBlack);
alpha = img.a;

input pixel image img;
param float lines = 2.0 [1.0, 16.0];
param float depth = 0.5 [0.0, 1.0];
param float rollSpeed = 0.0 [-10.0, 10.0];
stripe = 0.5 + 0.5 * cos((uv.y * res.y + t * rollSpeed) * 3.14159265 / max(lines, 1.0));
col = img.rgb * (1.0 - depth * stripe);
alpha = img.a;

# Procedural dirt and ghost discs; no extra image pin required.
input pixel image img;
param float dirtAmount = 0.25 [0.0, 1.0];
param float flareX = 0.75 [0.0, 1.0];
param float flareY = 0.7 [0.0, 1.0];
param float flareStrength = 0.3 [0.0, 2.0];
param float ghosts = 4.0 [1.0, 8.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
fpos = vec2((flareX - 0.5) * aspect, flareY - 0.5);
lum = dot(img.rgb, vec3(0.2126, 0.7152, 0.0722));
dirt = pow(0.5 + 0.5 * sin(p.x * 43.0 + sin(p.y * 27.0)) * cos(p.y * 39.0), 4.0);
flare = 0.0;
centre = fpos * 1.000000;
disc = 1.0 - smoothstep(0.017500, 0.035000, length(p - centre));
flare += disc * step(0.5, ghosts) / 1.0;
centre = fpos * 0.650000;
disc = 1.0 - smoothstep(0.023500, 0.047000, length(p - centre));
flare += disc * step(1.5, ghosts) / 2.0;
centre = fpos * 0.300000;
disc = 1.0 - smoothstep(0.029500, 0.059000, length(p - centre));
flare += disc * step(2.5, ghosts) / 3.0;
centre = fpos * -0.050000;
disc = 1.0 - smoothstep(0.035500, 0.071000, length(p - centre));
flare += disc * step(3.5, ghosts) / 4.0;
centre = fpos * -0.400000;
disc = 1.0 - smoothstep(0.041500, 0.083000, length(p - centre));
flare += disc * step(4.5, ghosts) / 5.0;
centre = fpos * -0.750000;
disc = 1.0 - smoothstep(0.047500, 0.095000, length(p - centre));
flare += disc * step(5.5, ghosts) / 6.0;
centre = fpos * -1.100000;
disc = 1.0 - smoothstep(0.053500, 0.107000, length(p - centre));
flare += disc * step(6.5, ghosts) / 7.0;
centre = fpos * -1.450000;
disc = 1.0 - smoothstep(0.059500, 0.119000, length(p - centre));
flare += disc * step(7.5, ghosts) / 8.0;
col = img.rgb + dirtAmount * dirt * lum + flareStrength * flare * vec3(1.0, 0.7, 0.4);
alpha = img.a;

# mode: 0 = to polar, 1 = from polar. Twist is measured in turns.
input pixel image img;
param float mode = 0.0 [0.0, 1.0];
param float twist = 0.0 [-2.0, 2.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
radius = length(p);
toPolar = vec2(fract(atan2(p.y, p.x + 0.000001) / 6.2831853 + 0.5 + twist * radius), radius * 2.0);
angle = (uv.x - 0.5 - twist * uv.y * 0.5) * 6.2831853;
fromPolar = vec2(cos(angle) * uv.y * 0.5 / aspect, sin(angle) * uv.y * 0.5) + 0.5;
c = img(mix(toPolar, fromPolar, step(0.5, mode)));
col = c.rgb;
alpha = c.a;

# radial: 0 = horizontal linear split, 1 = radial split.
input pixel image img;
param float amount = 0.01 [0.0, 0.1];
param float radial = 1.0 [0.0, 1.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
dir = mix(vec2(1.0, 0.0), p, radial);
offset = vec2(dir.x / aspect, dir.y) * amount;
r = img(uv + offset);
g = img(uv);
b = img(uv - offset);
col = vec3(r.r, g.g, b.b);
alpha = g.a;

# Editable 16-tap counterpart to the Effects radialblur node.
input pixel image img;
param float amount = 0.2 [0.0, 1.0];
param float centreX = 0.5 [0.0, 1.0];
param float centreY = 0.5 [0.0, 1.0];
centre = vec2(centreX, centreY);
p = vec2((uv.x - centre.x) * aspect, uv.y - centre.y);
dir = vec2(p.x / aspect, p.y);
sum = vec4(0.0);
sum += img(uv - dir * amount * 0.00000000) * 1.00000000;
sum += img(uv - dir * amount * 0.06666667) * 0.96666667;
sum += img(uv - dir * amount * 0.13333333) * 0.93333333;
sum += img(uv - dir * amount * 0.20000000) * 0.90000000;
sum += img(uv - dir * amount * 0.26666667) * 0.86666667;
sum += img(uv - dir * amount * 0.33333333) * 0.83333333;
sum += img(uv - dir * amount * 0.40000000) * 0.80000000;
sum += img(uv - dir * amount * 0.46666667) * 0.76666667;
sum += img(uv - dir * amount * 0.53333333) * 0.73333333;
sum += img(uv - dir * amount * 0.60000000) * 0.70000000;
sum += img(uv - dir * amount * 0.66666667) * 0.66666667;
sum += img(uv - dir * amount * 0.73333333) * 0.63333333;
sum += img(uv - dir * amount * 0.80000000) * 0.60000000;
sum += img(uv - dir * amount * 0.86666667) * 0.56666667;
sum += img(uv - dir * amount * 0.93333333) * 0.53333333;
sum += img(uv - dir * amount * 1.00000000) * 0.50000000;
c = sum / 12.0;
col = c.rgb;
alpha = c.a;

param float angle = 45.0 [0.0, 360.0];
param float speed = 0.5 [0.0, 5.0];
rad = angle * 0.01745329;
dir = vec2(cos(rad), sin(rad));
d = dot(uv - 0.5, dir) + 0.5 + sin(t * speed) * 0.1;
col = mix(vec3(0.1, 0.2, 0.8), vec3(1.0, 0.4, 0.2), clamp(d, 0.0, 1.0));

param float freq = 24.0 [2.0, 60.0];
param float speed = 3.0 [0.1, 10.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
d = length(p);
wave = sin(d * freq - t * speed);
col = vec3(0.5 + 0.5 * wave, 0.4 + 0.3 * cos(d * freq * 0.5), 0.8 + 0.2 * wave);

param float speed = 1.5 [0.1, 6.0];
param float saturation = 0.8 [0.0, 1.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
d = length(p);
angle = atan2(p.y, p.x);
hue = fract(angle / 6.283185 + t * 0.1 * speed);
r = clamp(abs(fract(hue + 1.0) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
g = clamp(abs(fract(hue + 0.6666) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
b = clamp(abs(fract(hue + 0.3333) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
rgb = mix(vec3(1.0), vec3(r, g, b), saturation);
col = rgb * (0.6 + 0.4 * sin(d * 20.0 - t * speed));

param float freq = 18.0 [2.0, 60.0];
param float speed = 2.5 [0.1, 10.0];
param float rings = 8.0 [1.0, 20.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
c1 = vec2(-0.15, 0.0);
c2 = vec2(0.15, 0.0);
p1 = length(p - c1);
p2 = length(p - c2);
w1 = sin(p1 * freq * rings - t * speed);
w2 = sin(p2 * freq * rings + t * speed);
val = 0.5 + 0.25 * (w1 + w2);
col = vec3(val, val * 0.7, 1.0 - val);

param float feed = 0.055 [0.01, 0.09];
param float kill = 0.062 [0.03, 0.075];
param float dA = 1.0 [0.0, 1.0];
param float dB = 0.5 [0.0, 1.0];
param float seed = 0.06 [0.0, 0.5];

param float speed = 0.5 [0.0, 3.0];
param float swirl = 2.5 [0.0, 10.0];
param float decay = 0.99 [0.9, 1.0];
param float amount = 0.6 [0.0, 1.0];
state float D = 0 [clamp];
q = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);

param float speed = 0.8 [0.1, 4.0];
param float scale = 4.5 [1.0, 15.0];
param float warp = 1.6 [0.2, 4.0];
p = vec2(uv.x * aspect, uv.y) * scale;
q = vec2(sin(p.x + t * speed), cos(p.y + t * speed * 0.8));
r = vec2(sin(p.y + q.x * warp + t * speed * 0.6), cos(p.x + q.y * warp - t * speed * 0.7));
f = sin(p.x + r.x * warp) * cos(p.y + r.y * warp);
v = 0.5 + 0.5 * f;
col = vec3(0.5 + 0.5 * cos(6.283185 * (v + 0.0)), 0.5 + 0.5 * cos(6.283185 * (v + 0.33)), 0.5 + 0.5 * cos(6.283185 * (v + 0.67)));

param float scale = 20.0 [4.0, 60.0];
param float speed = 1.0 [0.1, 5.0];
param float contrast = 2.5 [1.0, 6.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5) * scale;
w1 = cos(p.x + t * speed);
w2 = cos(p.x * 0.8090 + p.y * 0.5878 - t * speed * 0.9);
w3 = cos(p.x * 0.3090 + p.y * 0.9511 + t * speed * 0.8);
w4 = cos(-p.x * 0.3090 + p.y * 0.9511 - t * speed * 0.7);
w5 = cos(-p.x * 0.8090 + p.y * 0.5878 + t * speed * 0.6);
v = (w1 + w2 + w3 + w4 + w5) / 5.0;
bands = 0.5 + 0.5 * sin(v * 3.14159 * contrast);
col = vec3(bands * 0.9, bands * 0.5 + 0.3 * sin(t + v * 4.0), 1.0 - bands * 0.6);

param float scale = 6.0 [1.0, 24.0];
param float jitter = 0.9 [0.0, 1.0];
param float speed = 0.6 [0.0, 3.0];
p = vec2(uv.x * aspect, uv.y) * scale;
g = floor(p - 0.5);
q1 = g;
h1 = fract(sin(dot(q1, vec2(127.1, 311.7))) * 43758.5453);
f1 = q1 + vec2(0.5 + jitter * 0.45 * sin(t * speed + 6.2832 * h1), 0.5 + jitter * 0.45 * cos(t * speed * 1.31 + 6.2832 * fract(h1 * 17.13)));
d1 = length(f1 - p);
q2 = g + vec2(1.0, 0.0);
h2 = fract(sin(dot(q2, vec2(127.1, 311.7))) * 43758.5453);
f2 = q2 + vec2(0.5 + jitter * 0.45 * sin(t * speed + 6.2832 * h2), 0.5 + jitter * 0.45 * cos(t * speed * 1.31 + 6.2832 * fract(h2 * 17.13)));
d2 = length(f2 - p);
q3 = g + vec2(0.0, 1.0);
h3 = fract(sin(dot(q3, vec2(127.1, 311.7))) * 43758.5453);
f3 = q3 + vec2(0.5 + jitter * 0.45 * sin(t * speed + 6.2832 * h3), 0.5 + jitter * 0.45 * cos(t * speed * 1.31 + 6.2832 * fract(h3 * 17.13)));
d3 = length(f3 - p);
q4 = g + vec2(1.0, 1.0);
h4 = fract(sin(dot(q4, vec2(127.1, 311.7))) * 43758.5453);
f4 = q4 + vec2(0.5 + jitter * 0.45 * sin(t * speed + 6.2832 * h4), 0.5 + jitter * 0.45 * cos(t * speed * 1.31 + 6.2832 * fract(h4 * 17.13)));
d4 = length(f4 - p);
best = if(d2 < d1, h2, h1);
bd = min(d1, d2);
best = if(d3 < bd, h3, best);
bd = min(bd, d3);
best = if(d4 < bd, h4, best);
bd = min(bd, d4);
core = 1.0 - smoothstep(0.0, 0.55, bd);
cell = vec3(0.5 + 0.5 * sin(6.2832 * best), 0.5 + 0.5 * sin(6.2832 * best + 2.094), 0.5 + 0.5 * sin(6.2832 * best + 4.188));
col = cell * (0.28 + 0.72 * core);

param float cellSize = 24.0 [6.0, 60.0];
param float contrast = 1.4 [0.5, 3.0];
p = vec2(uv.x * aspect, uv.y) * cellSize;
cell = floor(p);
f = fract(p) - 0.5;
lum = (col.r * 0.299 + col.g * 0.587 + col.b * 0.114) * contrast;
jitter = fract(sin(dot(cell, vec2(12.9898, 78.233))) * 43758.5453) * 0.15;
radius = sqrt(clamp(lum + jitter, 0.0, 1.0)) * 0.5;
edge = length(f) - radius;
dotMask = 1.0 - smoothstep(0.0, 0.03, edge);
col = vec3(dotMask);

param float cellScale = 6.0 [2.0, 16.0];
param float density = 40.0 [10.0, 100.0];
param float speed = 1.2 [0.0, 4.0];
param float drift = 0.05 [0.0, 0.3];
p = vec2(uv.x * aspect, uv.y);
cell = floor(p * cellScale);
hash = fract(sin(dot(cell, vec2(91.7, 57.3))) * 43758.5453);
ang = hash * 6.283185 + t * drift;
flowDir = vec2(cos(ang), sin(ang));
along = dot(p, flowDir);
streak = 0.5 + 0.5 * sin(along * density - t * speed);
col = vec3(streak * 0.85, streak * 0.55 + 0.1, 1.0 - streak * 0.6);

param float pupilSize = 0.10 [0.05, 0.18];
param float irisSize = 0.24 [0.15, 0.32];
param float lidClose = 0.0 [0.0, 1.0];
param float irisFiberFreq = 24.0 [8.0, 48.0];
param float highlightSize = 0.035 [0.01, 0.07];
param float lashLength = 0.12 [0.05, 0.2];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
angle = atan2(p.y, p.x);
rad = length(p);
col = vec3(0.85, 0.68, 0.58);
eyeW = 0.34;
eyeH = 0.20;
norm = clamp(p.x / eyeW, -1.0, 1.0);
archTop = eyeH * (1.0 - norm * norm);
archBot = eyeH * 0.8 * (1.0 - norm * norm);
topLid = archTop * (1.0 - 0.92 * lidClose);
botLid = archBot * (1.0 - 0.15 * lidClose);
eyeOpen = smoothstep(-botLid - 0.01, -botLid + 0.01, p.y) * (1.0 - smoothstep(topLid - 0.01, topLid + 0.01, p.y));
col = mix(col, vec3(0.95, 0.94, 0.9), eyeOpen);
irisMask = (1.0 - smoothstep(irisSize, irisSize + 0.008, rad)) * eyeOpen;
fiber = 0.5 + 0.5 * sin(angle * irisFiberFreq + rad * 10.0);
irisBase = mix(vec3(0.25, 0.5, 0.35), vec3(0.15, 0.35, 0.25), fiber);
irisShade = smoothstep(0.0, irisSize, rad);
irisColor = mix(vec3(0.05, 0.15, 0.1), irisBase, irisShade);
col = mix(col, irisColor, irisMask);
pupilMask = (1.0 - smoothstep(pupilSize, pupilSize + 0.006, rad)) * eyeOpen;
col = mix(col, vec3(0.02, 0.02, 0.03), pupilMask);
specD = length(p - vec2(-pupilSize * 0.5, pupilSize * 0.5));
specMask = (1.0 - smoothstep(0.0, highlightSize, specD)) * eyeOpen;
col = mix(col, vec3(1.0), specMask);
spec2D = length(p - vec2(irisSize * 0.3, -irisSize * 0.25));
spec2Mask = (1.0 - smoothstep(0.0, highlightSize * 0.4, spec2D)) * irisMask;
col = mix(col, vec3(1.0), spec2Mask * 0.6);
topCrease = 1.0 - smoothstep(0.0, 0.01, abs(p.y - topLid));
botCrease = 1.0 - smoothstep(0.0, 0.01, abs(p.y + botLid));
col = mix(col, vec3(0.3, 0.18, 0.15), topCrease * 0.6);
col = mix(col, vec3(0.3, 0.18, 0.15), botCrease * 0.4);
lashRoot1 = vec2(0.30, 0.03);
lashDir1 = vec2(cos(0.35), sin(0.35));
lp1 = p - lashRoot1;
along1 = lp1.x * lashDir1.x + lp1.y * lashDir1.y;
perp1 = -lp1.x * lashDir1.y + lp1.y * lashDir1.x;
lash1 = (1.0 - smoothstep(0.0, 0.004, abs(perp1))) * smoothstep(0.0, 0.01, along1) * (1.0 - smoothstep(lashLength - 0.01, lashLength, along1));
col = mix(col, vec3(0.08, 0.05, 0.05), lash1);
lashRoot2 = vec2(0.20, 0.08);
lashDir2 = vec2(cos(0.55), sin(0.55));
lp2 = p - lashRoot2;
along2 = lp2.x * lashDir2.x + lp2.y * lashDir2.y;
perp2 = -lp2.x * lashDir2.y + lp2.y * lashDir2.x;
lash2 = (1.0 - smoothstep(0.0, 0.004, abs(perp2))) * smoothstep(0.0, 0.01, along2) * (1.0 - smoothstep(lashLength - 0.01, lashLength, along2));
col = mix(col, vec3(0.08, 0.05, 0.05), lash2);
lashRoot3 = vec2(0.08, 0.10);
lashDir3 = vec2(cos(0.75), sin(0.75));
lp3 = p - lashRoot3;
along3 = lp3.x * lashDir3.x + lp3.y * lashDir3.y;
perp3 = -lp3.x * lashDir3.y + lp3.y * lashDir3.x;
lash3 = (1.0 - smoothstep(0.0, 0.004, abs(perp3))) * smoothstep(0.0, 0.01, along3) * (1.0 - smoothstep(lashLength - 0.01, lashLength, along3));
col = mix(col, vec3(0.08, 0.05, 0.05), lash3);

param float horizonY = 0.42 [0.25, 0.55];
param float sunY = 0.14 [-0.05, 0.35];
param float sunSize = 0.07 [0.03, 0.15];
param float ridgeFreq = 3.0 [1.0, 8.0];
param float hazeAmount = 0.5 [0.0, 1.0];
param float reflectAmount = 0.35 [0.0, 1.0];
param float fogDensity = 0.5 [0.0, 1.0];
skyGrad = smoothstep(horizonY, 1.0, uv.y);
skyColor = mix(vec3(1.0, 0.7, 0.45), vec3(0.05, 0.08, 0.25), skyGrad);
col = skyColor;
sunPos = vec2(0.5, horizonY + sunY);
sunD = vec2((uv.x - sunPos.x) * aspect, uv.y - sunPos.y);
sunDist = length(sunD);
sunGlowMask = 1.0 - smoothstep(sunSize, sunSize * 3.0, sunDist);
sunDiskMask = 1.0 - smoothstep(sunSize, sunSize + 0.01, sunDist);
col = mix(col, vec3(1.0, 0.85, 0.6), sunGlowMask * 0.5);
col = mix(col, vec3(1.0, 0.95, 0.8), sunDiskMask);
p = vec2(uv.x * aspect, uv.y);
layer3Height = horizonY * 0.65 + 0.09 * abs(sin(p.x * ridgeFreq * 0.6 + 0.7)) + 0.035 * abs(sin(p.x * ridgeFreq * 1.7 + 2.1));
mask3 = 1.0 - smoothstep(layer3Height - 0.004, layer3Height + 0.004, uv.y);
layer3Color = mix(vec3(0.55, 0.62, 0.72), skyColor, hazeAmount * 0.7);
col = mix(col, layer3Color, mask3);
layer2Height = horizonY * 0.50 + 0.13 * abs(sin(p.x * ridgeFreq * 1.1 + 2.4)) + 0.05 * abs(sin(p.x * ridgeFreq * 2.6 + 0.9));
mask2 = 1.0 - smoothstep(layer2Height - 0.004, layer2Height + 0.004, uv.y);
layer2Color = mix(vec3(0.32, 0.4, 0.5), skyColor, hazeAmount * 0.35);
col = mix(col, layer2Color, mask2);
layer1Height = horizonY * 0.34 + 0.16 * abs(sin(p.x * ridgeFreq * 1.6 + 4.1)) + 0.06 * abs(sin(p.x * ridgeFreq * 3.3 + 1.6));
mask1 = 1.0 - smoothstep(layer1Height - 0.004, layer1Height + 0.004, uv.y);
layer1Color = vec3(0.10, 0.13, 0.18);
col = mix(col, layer1Color, mask1);
groundMask = 1.0 - smoothstep(horizonY - 0.01, horizonY + 0.01, uv.y);
waterBase = vec3(0.08, 0.12, 0.2);
col = mix(col, waterBase, groundMask);
reflPos = vec2(0.5, horizonY - sunY);
reflD = vec2((uv.x - reflPos.x) * aspect, (uv.y - reflPos.y) * 0.35);
reflDist = length(reflD);
reflGlow = (1.0 - smoothstep(sunSize * 0.5, sunSize * 2.5, reflDist)) * groundMask;
col = mix(col, vec3(1.0, 0.85, 0.6), reflGlow * reflectAmount);
fog = smoothstep(horizonY - 0.15, horizonY, uv.y) * groundMask;
col = mix(col, vec3(0.6, 0.65, 0.7), fog * fogDensity * 0.5);

param float size = 0.30 [0.15, 0.45];
param float earSize = 0.15 [0.05, 0.3];
param float squint = 0.8 [0.0, 1.0];
param float stripes = 0.4 [0.0, 1.0];
param float warmth = 0.0 [-0.3, 0.3];
param float shine = 0.35 [0.0, 1.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
rad = length(p);
lp = vec2(abs(p.x) - size * 0.62, p.y - size * 0.60);
earH = earSize * 1.7;
earW = earSize * 0.95;
taper = clamp(lp.y / max(earH, 0.0001), 0.0, 1.0);
edgeX = earW * (1.0 - taper);
earSide = 1.0 - smoothstep(edgeX - 0.004, edgeX + 0.004, abs(lp.x));
earTop = 1.0 - smoothstep(earH - 0.01, earH + 0.01, lp.y);
earBot = smoothstep(-0.02, 0.01, lp.y);
earMask = earSide * earTop * earBot;
ilp = lp - vec2(0.0, earH * 0.12);
iearH = earH * 0.6;
iearW = earW * 0.5;
itaper = clamp(ilp.y / max(iearH, 0.0001), 0.0, 1.0);
iedgeX = iearW * (1.0 - itaper);
innerSide = 1.0 - smoothstep(iedgeX - 0.003, iedgeX + 0.003, abs(ilp.x));
innerTop = 1.0 - smoothstep(iearH - 0.01, iearH + 0.01, ilp.y);
innerBot = smoothstep(-0.01, 0.01, ilp.y);
innerEarMask = innerSide * innerTop * innerBot * earMask;
headMask = 1.0 - smoothstep(size - 0.01, size + 0.01, rad);
stripePattern = 0.5 + 0.5 * sin(p.y * 26.0 + p.x * 6.0);
stripeMask = stripes * clamp(stripePattern - 0.55, 0.0, 1.0) * 2.2 * headMask * smoothstep(-0.05, size * 0.5, p.y);
ep = vec2(abs(p.x) - size * 0.36, p.y - size * 0.08);
eyeR = size * 0.11;
roundEye = 1.0 - smoothstep(eyeR - 0.006, eyeR + 0.006, length(ep));
pupil = 1.0 - smoothstep(eyeR * 0.45 - 0.004, eyeR * 0.45 + 0.004, length(ep));
ex = ep.x / max(eyeR * 1.4, 0.0001);
arcY = eyeR * 0.9 * (1.0 - ex * ex);
arcDist = abs(ep.y - arcY);
arcEye = (1.0 - smoothstep(0.010, 0.014, arcDist)) * (1.0 - smoothstep(eyeR * 1.4 - 0.01, eyeR * 1.4 + 0.01, abs(ep.x)));
eyeMask = mix(roundEye, arcEye, squint);
pupilMask = pupil * (1.0 - squint);
noseCenter = p - vec2(0.0, -size * 0.08);
noseMask = 1.0 - smoothstep(size * 0.05 - 0.006, size * 0.05 + 0.006, length(noseCenter));
mp = vec2(abs(p.x) - size * 0.10, p.y + size * 0.16);
mx = mp.x / max(size * 0.22, 0.0001);
mouthY = -size * 0.07 * (1.0 - mx * mx);
mouthDist = abs(mp.y - mouthY);
mouthMask = (1.0 - smoothstep(0.006, 0.010, mouthDist)) * (1.0 - smoothstep(size * 0.22 - 0.01, size * 0.22 + 0.01, abs(mp.x)));
wDir1 = vec2(cos(0.12), sin(0.12));
wp1 = vec2(abs(p.x) - size * 0.34, p.y + size * 0.02);
wAlong1 = wp1.x * wDir1.x + wp1.y * wDir1.y;
wPerp1 = -wp1.x * wDir1.y + wp1.y * wDir1.x;
whisker1 = (1.0 - smoothstep(0.0025, 0.004, abs(wPerp1))) * smoothstep(0.0, 0.02, wAlong1) * (1.0 - smoothstep(size * 0.55, size * 0.6, wAlong1));
wDir2 = vec2(cos(-0.10), sin(-0.10));
wp2 = vec2(abs(p.x) - size * 0.34, p.y + size * 0.09);
wAlong2 = wp2.x * wDir2.x + wp2.y * wDir2.y;
wPerp2 = -wp2.x * wDir2.y + wp2.y * wDir2.x;
whisker2 = (1.0 - smoothstep(0.0025, 0.004, abs(wPerp2))) * smoothstep(0.0, 0.02, wAlong2) * (1.0 - smoothstep(size * 0.55, size * 0.6, wAlong2));
whiskerMask = clamp(whisker1 + whisker2, 0.0, 1.0);
furBase = mix(vec3(0.62 + warmth, 0.40, 0.20), vec3(0.90, 0.58, 0.30), clamp(1.0 - rad / max(size, 0.0001), 0.0, 1.0));
furShaded = mix(furBase, furBase * 0.55, stripeMask);
lightVec = p - vec2(-size * 0.32, size * 0.30);
highlight = shine * (1.0 - smoothstep(0.0, size * 0.6, length(lightVec)));
furFinal = mix(furShaded, vec3(1.0, 0.95, 0.85), highlight * 0.4);
col = mix(col, furFinal, headMask);
col = mix(col, furFinal, earMask);
col = mix(col, vec3(0.85, 0.45, 0.50), innerEarMask);
col = mix(col, vec3(0.05, 0.05, 0.05), eyeMask);
col = mix(col, vec3(0.02, 0.02, 0.02), pupilMask);
col = mix(col, vec3(0.85, 0.35, 0.40), noseMask);
col = mix(col, vec3(0.10, 0.08, 0.08), mouthMask);
col = mix(col, vec3(0.95, 0.95, 0.95), whiskerMask);

param float headW = 0.34 [0.22, 0.46];
param float headH = 0.40 [0.26, 0.52];
param float eyeSize = 0.09 [0.05, 0.14];
param float eyeGlow = 1.2 [0.4, 2.5];
param float scanSpeed = 2.0 [0.0, 8.0];
param float panelTint = 0.5 [0.0, 1.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
col = vec3(0.07, 0.08, 0.10);
headX = 1.0 - smoothstep(headW - 0.015, headW + 0.015, abs(p.x));
headY = 1.0 - smoothstep(headH - 0.015, headH + 0.015, abs(p.y));
head = headX * headY;
col = mix(col, vec3(0.72, 0.76, 0.80), head);
panelH = (1.0 - smoothstep(0.0, 0.004, abs(p.y - headH * 0.18))) * head;
col = mix(col, vec3(0.5, 0.54, 0.58), panelH * panelTint);
panelV = (1.0 - smoothstep(0.0, 0.004, abs(p.x))) * head;
col = mix(col, vec3(0.5, 0.54, 0.58), panelV * panelTint * 0.6);
eyeL = p - vec2(-0.14, 0.05);
eyeR = p - vec2(0.14, 0.05);
dL = length(eyeL);
dR = length(eyeR);
housingL = 1.0 - smoothstep(eyeSize, eyeSize + 0.02, dL);
housingR = 1.0 - smoothstep(eyeSize, eyeSize + 0.02, dR);
col = mix(col, vec3(0.06, 0.06, 0.08), housingL);
col = mix(col, vec3(0.06, 0.06, 0.08), housingR);
lensL = 1.0 - smoothstep(eyeSize * 0.62, eyeSize * 0.62 + 0.012, dL);
lensR = 1.0 - smoothstep(eyeSize * 0.62, eyeSize * 0.62 + 0.012, dR);
lensColor = vec3(0.2, 0.85, 1.0) * eyeGlow;
col = mix(col, lensColor, lensL);
col = mix(col, lensColor, lensR);
scanL = 0.5 + 0.5 * sin(eyeL.y * 40.0 - t * scanSpeed);
scanR = 0.5 + 0.5 * sin(eyeR.y * 40.0 - t * scanSpeed);
scanMaskL = lensL * smoothstep(0.82, 1.0, scanL);
scanMaskR = lensR * smoothstep(0.82, 1.0, scanR);
col = mix(col, vec3(1.0), scanMaskL * 0.5);
col = mix(col, vec3(1.0), scanMaskR * 0.5);
specL = length(eyeL - vec2(-eyeSize * 0.35, eyeSize * 0.35));
specR = length(eyeR - vec2(-eyeSize * 0.35, eyeSize * 0.35));
specMaskL = (1.0 - smoothstep(0.0, eyeSize * 0.18, specL)) * lensL;
specMaskR = (1.0 - smoothstep(0.0, eyeSize * 0.18, specR)) * lensR;
col = mix(col, vec3(1.0), specMaskL);
col = mix(col, vec3(1.0), specMaskR);
mouthW = 0.15;
mouthH = 0.085;
mouthY = -0.20;
mouthX = 1.0 - smoothstep(mouthW - 0.006, mouthW + 0.006, abs(p.x));
mouthYm = 1.0 - smoothstep(mouthH - 0.006, mouthH + 0.006, abs(p.y - mouthY));
mouthHousing = mouthX * mouthYm;
col = mix(col, vec3(0.04, 0.04, 0.05), mouthHousing);
bar1 = mouthHousing * (1.0 - smoothstep(0.0, 0.006, abs(p.y - mouthY - 0.05)));
bar2 = mouthHousing * (1.0 - smoothstep(0.0, 0.006, abs(p.y - mouthY - 0.017)));
bar3 = mouthHousing * (1.0 - smoothstep(0.0, 0.006, abs(p.y - mouthY + 0.017)));
bar4 = mouthHousing * (1.0 - smoothstep(0.0, 0.006, abs(p.y - mouthY + 0.05)));
col = mix(col, vec3(0.45, 0.5, 0.55), bar1);
col = mix(col, vec3(0.45, 0.5, 0.55), bar2);
col = mix(col, vec3(0.45, 0.5, 0.55), bar3);
col = mix(col, vec3(0.45, 0.5, 0.55), bar4);
antennaTop = headH + 0.12;
antennaStem = (1.0 - smoothstep(0.0, 0.006, abs(p.x))) * smoothstep(headH - 0.01, headH + 0.01, p.y) * (1.0 - smoothstep(antennaTop - 0.01, antennaTop + 0.01, p.y));
col = mix(col, vec3(0.55, 0.6, 0.65), antennaStem);
tipD = length(p - vec2(0.0, antennaTop));
tipMask = 1.0 - smoothstep(0.02, 0.032, tipD);
tipTint = vec3(1.0, 0.3, 0.3);
tipGlow = tipTint * (0.6 + 0.4 * sin(t * scanSpeed * 1.5));
col = mix(col, tipGlow, tipMask);

param float cloudScale = 3.0 [1.0, 8.0];
param float swirl = 2.0 [0.0, 6.0];
param float speed = 0.3 [0.0, 2.0];
param float coreGlow = 1.0 [0.2, 2.5];
param float colorShift = 0.0 [0.0, 1.0];
param float starDensity = 40.0 [10.0, 120.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
rad = length(p);
angle = atan2(p.y, p.x);
swirlAngle = angle + swirl * rad * 2.0 - t * speed * 0.5;
sp = vec2(cos(swirlAngle), sin(swirlAngle)) * rad;
freqA = cloudScale;
cA = sin(sp.x * freqA + t * speed) * cos(sp.y * freqA * 1.3 - t * speed * 0.7);
rB = vec2(sp.x * cos(0.65) - sp.y * sin(0.65), sp.x * sin(0.65) + sp.y * cos(0.65));
cB = sin(rB.x * freqA * 2.1 + t * speed * 1.4) * cos(rB.y * freqA * 1.7 - t * speed * 0.9);
rC = vec2(sp.x * cos(1.15) - sp.y * sin(1.15), sp.x * sin(1.15) + sp.y * cos(1.15));
cC = sin(rC.x * freqA * 3.7 + t * speed * 0.6) * cos(rC.y * freqA * 2.9 + t * speed * 1.1);
turb = (cA + 0.6 * cB + 0.35 * cC) / 1.95;
cloudVal = 0.5 + 0.5 * turb;
huey = cloudVal + colorShift;
cloudColor = vec3(0.5 + 0.5 * cos(6.283185 * (huey + 0.0)), 0.5 + 0.5 * cos(6.283185 * (huey + 0.33)), 0.5 + 0.5 * cos(6.283185 * (huey + 0.67)));
cloudColor = cloudColor * vec3(0.7, 0.5, 1.0);
col = cloudColor * (0.35 + 0.5 * cloudVal);
core = coreGlow * (0.15 / (rad * rad + 0.01));
glowTint = vec3(1.0, 0.9, 0.75);
col = col + glowTint * core * 0.15;
starP = vec2(uv.x * aspect, uv.y) * starDensity;
starCell = floor(starP);
starF = fract(starP) - 0.5;
starHash = fract(sin(dot(starCell, vec2(12.9898, 78.233))) * 43758.5453);
starHash2 = fract(sin(dot(starCell, vec2(39.346, 11.135))) * 53758.5453);
starOffset = vec2(starHash - 0.5, starHash2 - 0.5) * 0.7;
starDist = length(starF - starOffset);
starPresence = smoothstep(0.94, 1.0, starHash2);
twinkle = 0.5 + 0.5 * sin(t * 3.0 + starHash * 30.0);
starDot = (1.0 - smoothstep(0.0, 0.12, starDist)) * starPresence * (0.5 + 0.5 * twinkle);
col = col + vec3(1.0) * starDot;

param float pulseSpeed = 1.6 [0.5, 4.0];
param float tentacles = 8.0 [4.0, 16.0];
param float glow = 1.2 [0.2, 3.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
pulse = sin(t * pulseSpeed) * 0.06;
bellP = p - vec2(0.0, 0.1);
bellD = length(vec2(bellP.x * 1.3, bellP.y * (1.0 + pulse)));
bellMask = smoothstep(0.24, 0.22, bellD) * step(0.0, -bellP.y + 0.08);
rim = smoothstep(0.23, 0.20, bellD) - smoothstep(0.20, 0.16, bellD);
tentX = p.x + sin(p.y * 14.0 + t * pulseSpeed * 1.5) * 0.035 * (0.1 - p.y);
tentWave = sin(tentX * tentacles * 20.0) * step(p.y, 0.08) * step(-0.45, p.y);
tentMask = smoothstep(0.85, 0.98, tentWave) * (1.0 - smoothstep(-0.45, 0.05, p.y));
deepBlue = vec3(0.02, 0.04, 0.1);
neonCyan = vec3(0.1, 0.85, 0.95);
magenta = vec3(0.9, 0.2, 0.8);
jellyCol = mix(neonCyan, magenta, bellD * 3.5) * glow;
col = deepBlue + jellyCol * (bellMask * 0.6 + rim * 0.9 + tentMask * 0.85);

param float turns = 4.0 [1.0, 8.0];
param float expansion = 0.306 [0.1, 0.6];
param float iridSpeed = 1.0 [0.0, 4.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
r = length(p);
theta = atan2(p.y, p.x);
spiralCoord = (log(max(r, 0.001)) - theta * expansion) / 6.2831853;
chamber = fract(spiralCoord * turns);
chamberEdge = smoothstep(0.0, 0.08, chamber) * smoothstep(1.0, 0.92, chamber);
irid = 0.5 + 0.5 * sin(chamber * 12.0 + t * iridSpeed + theta);
shellCol = vec3(0.85 + 0.15 * irid, 0.65 + 0.25 * sin(chamber * 6.28), 0.45 + 0.4 * irid);
col = shellCol * chamberEdge * smoothstep(0.02, 0.06, r) * smoothstep(0.55, 0.48, r);

param float density = 12.0 [4.0, 30.0];
param float pulseSpeed = 2.0 [0.2, 5.0];
param float glow = 1.4 [0.2, 3.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
r = length(p);
v1 = sin(p.x * density + sin(p.y * density * 0.8 + t * 0.5));
v2 = cos(p.y * density + cos(p.x * density * 0.8 - t * 0.4));
veins = abs(v1 * v2);
branch = 1.0 - smoothstep(0.0, 0.12, veins);
pulse = sin(r * 25.0 - t * pulseSpeed) * 0.5 + 0.5;
slimeYellow = vec3(0.85, 0.95, 0.15) * glow;
col = slimeYellow * branch * (0.6 + 0.4 * pulse) + vec3(0.01, 0.03, 0.01);

param float spikes = 10.0 [4.0, 20.0];
param float spikeLen = 0.18 [0.05, 0.4];
param float sharpness = 8.0 [2.0, 20.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
r = length(p);
theta = atan2(p.y, p.x);
spikeMod = pow(abs(sin(theta * (spikes * 0.5))), sharpness) * spikeLen;
bodyR = 0.22 + spikeMod;
iso = smoothstep(bodyR + 0.015, bodyR - 0.015, r);
spec = pow(max(0.0, 1.0 - abs(r - bodyR * 0.7) * 5.0), 3.0);
darkFluid = vec3(0.05, 0.06, 0.08);
highlight = vec3(0.8, 0.85, 0.95) * spec;
col = mix(vec3(0.12, 0.13, 0.15), darkFluid + highlight, iso);

param float petals = 6.0 [3.0, 16.0];
param float speed = 0.8 [0.0, 3.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
r = length(p);
theta = atan2(p.y, p.x) + t * speed * 0.3;
petalR = 0.25 + 0.12 * cos(theta * petals) + 0.06 * cos(theta * petals * 2.0 - t * speed);
ring = abs(r - petalR);
mandala = smoothstep(0.025, 0.005, ring);
core = smoothstep(0.06, 0.02, r);
hue = theta / 6.2831853 + t * 0.1;
mandalaCol = vec3(0.5 + 0.5 * sin(hue * 6.28), 0.5 + 0.5 * sin(hue * 6.28 + 2.1), 0.5 + 0.5 * sin(hue * 6.28 + 4.2));
col = mandalaCol * (mandala + core);

param float scanSpeed = 3.0 [0.5, 8.0];
param float glow = 1.3 [0.3, 3.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
craniumD = length(vec2(p.x * 1.15, (p.y - 0.06) * 1.0));
cranium = smoothstep(0.24, 0.22, craniumD);
jaw = step(abs(p.x), 0.12) * step(-0.25, p.y) * step(p.y, -0.05);
skullBase = max(cranium, jaw);
eyeL = length(p - vec2(-0.08, 0.02));
eyeR = length(p - vec2(0.08, 0.02));
eyes = smoothstep(0.05, 0.038, min(eyeL, eyeR));
noseD = length(vec2(p.x * 1.8, p.y + 0.05));
nose = smoothstep(0.035, 0.025, noseD);
teeth = step(abs(p.x), 0.09) * step(-0.22, p.y) * step(p.y, -0.16) * (0.5 + 0.5 * sin(p.x * 140.0));
skullShape = clamp(skullBase - eyes - nose - teeth * 0.6, 0.0, 1.0);
scan = 0.75 + 0.25 * sin(p.y * 180.0 + t * scanSpeed);
holoCyan = vec3(0.1, 0.95, 0.85) * glow;
col = holoCyan * skullShape * scan + eyes * vec3(1.0, 0.2, 0.2) * 1.5;

param float speed = 1.5 [0.1, 5.0];
param float sunSize = 0.28 [0.1, 0.5];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
isSky = step(0.0, p.y);
sunD = length(p - vec2(0.0, 0.12));
sunStripe = step(0.35, fract(p.y * 30.0));
sunMask = (1.0 - smoothstep(sunSize - 0.01, sunSize, sunD)) * isSky * (if(p.y < 0.12, sunStripe, 1.0));
sunCol = mix(vec3(1.0, 0.85, 0.1), vec3(1.0, 0.15, 0.5), clamp((0.12 - p.y) * 4.0, 0.0, 1.0));
groundP = vec2(p.x / max(-p.y, 0.005), 1.0 / max(-p.y, 0.005) + t * speed);
gridX = 1.0 - smoothstep(0.0, 0.08, abs(fract(groundP.x * 2.0) - 0.5));
gridY = 1.0 - smoothstep(0.0, 0.08, abs(fract(groundP.y * 0.8) - 0.5));
grid = max(gridX, gridY) * (1.0 - isSky) * smoothstep(0.0, 0.15, -p.y);
gridCol = vec3(0.0, 0.9, 1.0);
skyGradient = mix(vec3(0.08, 0.02, 0.15), vec3(0.35, 0.05, 0.3), clamp(p.y * 2.0, 0.0, 1.0));
col = mix(skyGradient, sunCol, sunMask) + gridCol * grid;

param float waveHeight = 0.25 [0.05, 0.6];
param float speed = 1.2 [0.1, 4.0];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
waveY = sin(p.x * 5.0 - t * speed) * waveHeight + sin(p.x * 12.0 + t * speed * 0.7) * 0.06 - 0.05;
foam = sin(p.x * 35.0 - t * speed * 2.0) * 0.03;
isWater = step(p.y, waveY);
isFoam = step(p.y, waveY + foam) * (1.0 - isWater);
deepIndigo = vec3(0.06, 0.18, 0.38);
cerulean = vec3(0.2, 0.55, 0.75);
whiteFoam = vec3(0.95, 0.98, 1.0);
waterCol = mix(deepIndigo, cerulean, clamp((p.y + 0.5) / 0.8, 0.0, 1.0));
skyCream = vec3(0.92, 0.90, 0.82);
col = mix(skyCream, waterCol, isWater) + whiteFoam * isFoam;

param float every = 4.0 [1.0, 30.0];
param float seed = 0.3 [0.05, 0.6];
state float L = 0 [wrap];
d = 1.0 / res;
n = L(uv + vec2(d.x, 0.0)) + L(uv - vec2(d.x, 0.0)) + L(uv + vec2(0.0, d.y)) + L(uv - vec2(0.0, d.y)) + L(uv + d) + L(uv - d) + L(uv + vec2(d.x, -d.y)) + L(uv + vec2(-d.x, d.y));
h = fract(sin(dot(uv, vec2(12.9898, 78.233))) * 43758.5453);
first = 1.0 - step(0.5, age);

param float mu = 0.22 [0.05, 0.4];
param float sigma = 0.06 [0.005, 0.15];
param float rate = 0.1 [0.01, 0.4];
param float radius = 8.0 [2.0, 14.0];
param float seed = 0.6 [0.1, 1.0];
state float A = 0 [wrap];
d = 1.0 / res;

param float speed = 1.0 [0.0, 5.0];
param float freq = 10.0 [1.0, 30.0];
param float arms = 5.0 [1.0, 12.0];
param float warp = 1.0 [0.0, 3.0];
param float rate = 0.9 [0.5, 0.999];
state float A = 0 [wrap];
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
d = length(p);
ang = atan2(p.y, p.x);
spiral = sin(ang * arms + d * freq - t * speed);
fresh = step(0.0, spiral);

param float speed = 1.0 [0.1, 3.0];
param float boxSize = 0.05 [0.02, 0.1];
state float posX = 0.15;
state float posY = 0.1;
state float velX = 0.35;
state float velY = 0.28;
pos = vec2(posX, posY);
vel = vec2(velX, velY);
s = boxSize;
boundX = 0.5 * aspect - s;
boundY = 0.5 - s;
hitWallX = step(boundX, abs(pos.x + vel.x * dt * speed));
hitWallY = step(boundY, abs(pos.y + vel.y * dt * speed));
vel = vec2(vel.x * (1.0 - 2.0 * hitWallX), vel.y * (1.0 - 2.0 * hitWallY));
cA = vec2(0.3 * sin(t * 0.9), 0.22 * cos(t * 1.3));
cB = vec2(0.28 * cos(t * 0.7 + 1.0), 0.24 * sin(t * 1.1 + 2.0));
cC = vec2(0.25 * sin(t * 1.4 + 3.0), 0.3 * cos(t * 0.6 + 1.5));
cD = vec2(0.32 * cos(t * 0.5 + 2.5), 0.18 * sin(t * 1.6 + 0.5));
cE = vec2(0.2 * sin(t * 1.1 + 4.0), 0.28 * cos(t * 0.8 + 3.5));
cF = vec2(0.3 * cos(t * 1.3 + 1.7), 0.2 * sin(t * 0.9 + 2.9));
cG = vec2(0.22 * sin(t * 0.8 + 0.3), 0.26 * cos(t * 1.5 + 1.2));
cH = vec2(0.27 * cos(t * 1.0 + 3.3), 0.22 * sin(t * 1.2 + 0.8));
hitA = step(abs(pos.x - cA.x), 2.0 * s) * step(abs(pos.y - cA.y), 2.0 * s);
hitB = step(abs(pos.x - cB.x), 2.0 * s) * step(abs(pos.y - cB.y), 2.0 * s);
hitC = step(abs(pos.x - cC.x), 2.0 * s) * step(abs(pos.y - cC.y), 2.0 * s);
hitD = step(abs(pos.x - cD.x), 2.0 * s) * step(abs(pos.y - cD.y), 2.0 * s);
hitE = step(abs(pos.x - cE.x), 2.0 * s) * step(abs(pos.y - cE.y), 2.0 * s);
hitF = step(abs(pos.x - cF.x), 2.0 * s) * step(abs(pos.y - cF.y), 2.0 * s);
hitG = step(abs(pos.x - cG.x), 2.0 * s) * step(abs(pos.y - cG.y), 2.0 * s);
hitH = step(abs(pos.x - cH.x), 2.0 * s) * step(abs(pos.y - cH.y), 2.0 * s);
sumHit = hitA + hitB + hitC + hitD + hitE + hitF + hitG + hitH;
anyHit = step(0.5, sumHit);
vel = vel * (1.0 - 2.0 * anyHit);
pos = pos + vel * dt * speed;
posX = pos.x;
posY = pos.y;
velX = vel.x;
velY = vel.y;
p = vec2((uv.x - 0.5) * aspect, uv.y - 0.5);
